import itertools
# universe of region types: each element characterised by membership in (car,bird,plant,leaf)
types=[t for t in itertools.product([0,1],repeat=4)]
def valid(m):
    has=lambda f:any(f(*t) for t in m)
    if any(c and not b for c,b,p,l in m): return False
    if any(p and not l for c,b,p,l in m): return False
    if not has(lambda c,b,p,l:b and p): return False
    if not has(lambda c,b,p,l:c): return False  # categorical terms assumed non-empty
    return True
concl=[lambda m:any(b and c for c,b,p,l in m),lambda m:any(p and b for c,b,p,l in m),lambda m:any(l and p for c,b,p,l in m)]
res=[True,True,True]
for r in range(1,5):
    for m in itertools.combinations(types,r):
        if valid(m):
            for i,f in enumerate(concl):
                if not f(m): res[i]=False
